// Phone number validation and standardization function
function validateAndFormatPhone(phone, countryCode = 'PH') {
  // Remove all non-digit characters
  let cleaned = phone.toString().replace(/\D/g, '');

  // Country code mappings
  const countryCodes = {
    'PH': '63',  // Philippines
    'US': '1',   // United States
    'GB': '44',  // United Kingdom
    'AU': '61',  // Australia
    'CA': '1',   // Canada
    'SG': '65',  // Singapore
    'MY': '60',  // Malaysia
    'ID': '62',  // Indonesia
    'TH': '66',  // Thailand
    'VN': '84',  // Vietnam
    'JP': '81',  // Japan
    'KR': '82',  // South Korea
    'CN': '86',  // China
    'IN': '91',  // India
    'DE': '49',  // Germany
    'FR': '33',  // France
    'IT': '39',  // Italy
    'ES': '34',  // Spain
    'BR': '55'   // Brazil
  };

  const defaultCountryCode = countryCodes[countryCode] || '63';

  // Remove leading zero if present
  if (cleaned.startsWith('0')) {
    cleaned = cleaned.substring(1);
  }

  // Check if phone already has country code
  let hasCountryCode = false;
  for (const code of Object.values(countryCodes)) {
    if (cleaned.startsWith(code)) {
      hasCountryCode = true;
      break;
    }
  }

  // Add country code if missing
  if (!hasCountryCode) {
    cleaned = defaultCountryCode + cleaned;
  }

  // Validate length (should be between 10-15 digits including country code)
  if (cleaned.length < 10 || cleaned.length > 15) {
    throw new Error(`Invalid phone number length: ${cleaned.length} digits. Must be between 10-15 digits including country code.`);
  }

  // Format with plus sign for international format
  const formattedPhone = '+' + cleaned;

  return {
    original: phone,
    cleaned: cleaned,
    formatted: formattedPhone,
    countryCode: cleaned.substring(0, countryCodes[countryCode]?.length || 2),
    isValid: true
  };
}

const phoneInput = $input.first().json.phone;
const countryCode = $input.first().json.country_code || 'PH';

try {
  const result = validateAndFormatPhone(phoneInput, countryCode);
  return {
    ...$input.first().json,
    phone_original: result.original,
    phone: result.formatted,
    phone_cleaned: result.cleaned,
    phone_country_code: result.countryCode,
    phone_validated: true
  };
} catch (error) {
  return {
    ...$input.first().json,
    phone_original: phoneInput,
    phone: null,
    phone_validated: false,
    phone_validation_error: error.message
  };
}

// Check if customer already exists
const existingCustomer = $input.first().json;
const hasExisting = existingCustomer && Object.keys(existingCustomer).length > 0;

return {
  ...$input.first().json,
  customer_exists: hasExisting,
  customer_id: hasExisting ? existingCustomer.id : null
};

// Generate customer ID
const generateCustomerId = () => {
  return 'cus_' + Math.random().toString(36).substring(2, 15) + Date.now().toString(36);
};

const customerData = $input.first().json;

return {
  id: generateCustomerId(),
  email: customerData.email || null,
  phone: customerData.phone,
  first_name: customerData.first_name || null,
  last_name: customerData.last_name || null,
  hashed_password: customerData.password ? null : null, // Password should be hashed separately
  is_active: true,
  has_account: true,
  metadata: {
    phone_original: customerData.phone_original,
    phone_cleaned: customerData.phone_cleaned,
    phone_country_code: customerData.phone_country_code,
    registered_at: new Date().toISOString(),
    ...customerData.metadata
  },
  created_at: new Date(),
  updated_at: new Date()
};

// Return success response with customer data
const customer = $input.first().json;

return {
  success: true,
  message: 'Customer registered successfully',
  customer: {
    id: customer.id,
    phone: customer.phone,
    email: customer.email,
    first_name: customer.first_name,
    last_name: customer.last_name,
    created_at: customer.created_at
  }
};

// Return error for existing customer
const existing = $input.first().json;

return {
  success: false,
  error: 'Customer already exists',
  customer: {
    id: existing.customer_id,
    phone: existing.phone,
    email: existing.email
  }
};

// Return validation error response
const errorData = $input.first().json;

return {
  success: false,
  error: 'Phone number validation failed',
  details: errorData.phone_validation_error,
  phone_original: errorData.phone_original
};
